SELECT fhir_Appointment.Id, fhir_Appointment.StartTime, fhir_Appointment.EndTime, fhir_Appointment.MinutesDuration, fhir_Appointment.Status, fhir_Appointment.ServiceCategory, fhir_Appointment.ServiceType, fhir_Appointment.ReasonCode, fhir_Appointment.Description, fhir_Appointment.PatientReference, sync_ScheduledPatient.PatientId, sync_ScheduledPatient.DisplayName, sync_ScheduledPatient.ContactPhone, fhir_Appointment.PractitionerReference FROM fhir_Appointment INNER JOIN sync_ScheduledPatient ON fhir_Appointment.PatientReference = sync_ScheduledPatient.PatientId WHERE fhir_Appointment.PractitionerReference = @practitionerRef AND fhir_Appointment.StartTime >= @dateStart AND fhir_Appointment.StartTime < @dateEnd ORDER BY fhir_Appointment.StartTime 